import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"What is wg-easy-mcp?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1786899786000}`),a={name:`guide/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="what-is-wg-easy-mcp" tabindex="-1">What is wg-easy-mcp? <a class="header-anchor" href="#what-is-wg-easy-mcp" aria-label="Permalink to “What is wg-easy-mcp?”">​</a></h1><p><a href="https://github.com/wg-easy/wg-easy" target="_blank" rel="noreferrer">wg-easy</a> is a self-hosted web UI for WireGuard. <code>wg-easy-mcp</code> puts its REST API behind the <a href="https://modelcontextprotocol.io" target="_blank" rel="noreferrer">Model Context Protocol</a>, so an MCP client — Claude Code, Claude Desktop, Codex, the MCP Inspector — can administer the VPN directly.</p><p>In practice that means asking for things like:</p><ul><li><em>&quot;Which VPN clients haven&#39;t connected in the last month?&quot;</em></li><li><em>&quot;Create a client called <code>laptop-lena</code> that expires at the end of the quarter.&quot;</em></li><li><em>&quot;Disable <code>old-contractor</code> and show me the remaining enabled clients.&quot;</em></li><li><em>&quot;Give me the QR code for <code>phone-tom</code>.&quot;</em></li></ul><h2 id="how-it-fits-together" tabindex="-1">How it fits together <a class="header-anchor" href="#how-it-fits-together" aria-label="Permalink to “How it fits together”">​</a></h2><p>The server speaks MCP over <strong>stdio</strong> and talks to wg-easy over its <strong>HTTP REST API</strong> using Basic Authentication — the same credentials as the web UI login. It holds no database and caches nothing except short-lived delete confirmation tokens; wg-easy stays the single source of truth.</p><h2 id="what-it-is-not" tabindex="-1">What it is not <a class="header-anchor" href="#what-it-is-not" aria-label="Permalink to “What it is not”">​</a></h2><ul><li><strong>Not a WireGuard implementation.</strong> Everything routes through wg-easy&#39;s API; key generation, IP allocation and the interface itself stay wg-easy&#39;s job.</li><li><strong>Not a wg-easy installer.</strong> You need a running wg-easy v15 instance first.</li><li><strong>Not multi-instance.</strong> One server process targets exactly one <code>WG_EASY_URL</code>. Register the server twice with different environments to manage two VPNs.</li></ul><h2 id="version-support" tabindex="-1">Version support <a class="header-anchor" href="#version-support" aria-label="Permalink to “Version support”">​</a></h2><p>This server targets <strong>wg-easy v15 and newer</strong>. The wg-easy REST API is <a href="https://wg-easy.github.io/wg-easy/latest/advanced/api/" target="_blank" rel="noreferrer">not yet declared stable</a>, so a wg-easy upgrade can change endpoint shapes. If a tool starts returning schema errors after a wg-easy update, that is the first thing to check.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next steps”">​</a></h2><ul><li><a href="/guide/getting-started">Getting started</a> — install it and make the first call</li><li><a href="/guide/clients">Connecting clients</a> — Claude Code, Claude Desktop, Codex, Docker</li><li><a href="/guide/security">Security</a> — what the credentials grant and how output is guarded</li><li><a href="/reference/tools">Tools reference</a> — every tool, argument by argument</li></ul>`,12)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};